  seek.push(await video.evaluate(v=>{v.currentTime=15;return new Promise(r=>{let f=()=>{v.removeEventListener('seeked',f);r(v.currentTime)};v.addEventListener('seeked',f);setTimeout(()=>r(v.currentTime),1500)})}));
 }
